// En Spring Boot real, importarías:
// import jakarta.persistence.*;

// @Entity — le dice a Spring que esta clase es una tabla en la BD
// @Table(name = "productos") — opcional, personaliza el nombre de la tabla
public class Producto {

    // @Id — esta es la clave primaria
    // @GeneratedValue(strategy = GenerationType.IDENTITY) — auto-incremento
    private Long id;

    // @Column(nullable = false) — en Spring Boot haría el campo obligatorio
    private String nombre;
    private double precio;
    private int stock;

    // Constructor vacío (requerido por JPA)
    public Producto() {}

    // Constructor completo
    public Producto(Long id, String nombre, double precio, int stock) {
        this.id = id;
        this.nombre = nombre;
        this.precio = precio;
        this.stock = stock;
    }

    // Getter para id
    public Long getId() { return id; }

    // Getter para nombre
    public String getNombre() { return nombre; }

    // Getter para precio
    public double getPrecio() { return precio; }

    public int getStock() { return stock; }

    // Setters
    public void setNombre(String nombre) { this.nombre = nombre; }
    public void setPrecio(double precio) { this.precio = precio; }
    public void setStock(int stock) { this.stock = stock; }

    @Override
    public String toString() {
        return "Producto{id=" + id + ", nombre='" + nombre + "', precio=$" + precio + ", stock=" + stock + "}";
    }

    public static void main(String[] args) {
        Producto p1 = new Producto(1L, "Laptop", 1200.00, 15);
        Producto p2 = new Producto(2L, "Mouse", 25.50, 100);
        Producto p3 = new Producto(3L, "Teclado", 45.00, 75);

        System.out.println("=== Productos en BD (simulado) ===");
        System.out.println(p1);
        System.out.println(p2);
        System.out.println(p3);

        System.out.println("\nNombre del producto 1: " + p1.getNombre());
        System.out.println("Precio del producto 2: $" + p2.getPrecio());
        System.out.println("Stock disponible p3: " + p3.getStock() + " unidades");
    }
}
